// NOTE: Assertions have been autogenerated by utils/update_cc_test_checks.py UTC_ARGS: --version 6
// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -O2 -relaxed-aliasing -Wno-missing-declarations -fsanitize=array-bounds -fsanitize-trap=array-bounds -emit-llvm -o - %s | FileCheck %s

// Tests that the count used by __builtin_dynamic_object_size and by
// -fsanitize=array-bounds is loaded the same way an ordinary access to the
// count field would be. It used to be loaded as a raw integer of the count's
// type, with 'int' alignment, at a whole-byte offset, which:
//   - read the wrong bits for a bit-field count, from a misaligned address that
//     could overlap the flexible array member,
//   - claimed 4-byte alignment for counts that aren't 4-byte aligned (e.g. a
//     'short' at offset 2, or any count in a packed struct),
//   - dropped 'volatile', and
//   - used the in-register rather than in-memory type of a '_BitInt' count.

#define __bdos(P) __builtin_dynamic_object_size(P, 1)

// A bit-field count that doesn't start at bit 0 of its storage unit.
struct bitfield_fam {
  unsigned flags : 3;
  unsigned count : 13;
  int array[] __attribute__((counted_by(count)));
};

struct bitfield_ptr {
  unsigned flags : 3;
  unsigned count : 13;
  int *buf __attribute__((counted_by(count)));
};

// CHECK-LABEL: define dso_local range(i64 0, 32765) i64 @test_bdos_bitfield_fam(
// CHECK-SAME: ptr nofree noundef readonly captures(none) [[P:%.*]]) local_unnamed_addr #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[BF_LOAD:%.*]] = load i16, ptr [[P]], align 4
// CHECK-NEXT:    [[TMP0:%.*]] = lshr i16 [[BF_LOAD]], 1
// CHECK-NEXT:    [[TMP1:%.*]] = and i16 [[TMP0]], 32764
// CHECK-NEXT:    [[FLEXIBLE_ARRAY_MEMBER_SIZE:%.*]] = zext nneg i16 [[TMP1]] to i64
// CHECK-NEXT:    ret i64 [[FLEXIBLE_ARRAY_MEMBER_SIZE]]
//
unsigned long test_bdos_bitfield_fam(struct bitfield_fam *p) {
  return __bdos(p->array);
}

